// Verified D1-only NCAAB (men's college basketball) team crosswalk:
//   Kalshi KXNCAAMB* code -> ESPN team id (+ Polymarket US cbb abbreviation when Polymarket lists the team).
//
// Data: ncaab-crosswalk.json, generated by scripts/gen-ncaab-crosswalk.js from REAL Kalshi + Polymarket US
// events and ESPN's D1 list (Kevin Oct 30 2026: D1-vs-D1 games only). Anything not in the table is UNMAPPED
// and stays that way: no guessing, no even-splitting of the Kalshi team blob. Non-D1 schools are never in it.
//
// Canonical NCAAB team identity in this worker = the Kalshi code (same as NCAAF / NBA); the ESPN id is the
// bridge to every venue's names (ncaab-d1.js resolves a display name to exactly one D1 team or to null).
'use strict';
const data = require('./ncaab-crosswalk.json');
const D1 = require('./ncaab-d1');

const byCode = new Map(); // KALSHI CODE -> { code, espnId, name, espn, p, pname }
const byPoly = new Map(); // poly abbr -> team
const byEspn = new Map(); // espn id -> team
for (const [code, t] of Object.entries(data.teams || {})) {
  if (!/^[A-Z]+$/.test(code) || !t || !t.espnId) continue;
  const id = String(t.espnId);
  if (byEspn.has(id)) { byCode.delete(byEspn.get(id).code); byEspn.set(id, null); continue; } // defensive: one team, one code
  if (byEspn.get(id) === null) continue;
  const team = { code, espnId: id, name: t.name, espn: t.espn || null, p: t.p && /^[a-z0-9]+$/.test(t.p) ? t.p : null, pname: t.pname || null };
  byCode.set(code, team);
  byEspn.set(id, team);
}
for (const [id, v] of [...byEspn]) if (v === null) byEspn.delete(id);
for (const t of byCode.values()) {
  if (!t.p) continue;
  if (byPoly.has(t.p)) { byPoly.get(t.p).p = null; t.p = null; continue; }
  byPoly.set(t.p, t);
}
const CODES = [...byCode.keys()].sort((a, b) => b.length - a.length);

// "NDVILL" -> { codes: ['ND','VILL'] } ONLY when exactly one reading uses two distinct known codes.
function splitBlob(blob) {
  const s = String(blob || '').toUpperCase();
  if (!/^[A-Z]+$/.test(s)) return null;
  const hits = [];
  for (const a of CODES) {
    if (!s.startsWith(a)) continue;
    const r = s.slice(a.length);
    if (r !== a && byCode.has(r)) hits.push([a, r]);
  }
  return hits.length === 1 ? { codes: hits[0] } : null;
}

const teamByCode = (code) => byCode.get(String(code || '').toUpperCase()) || null;
const teamByPoly = (abbr) => byPoly.get(String(abbr || '').toLowerCase()) || null;
const teamByEspn = (id) => byEspn.get(String(id || '')) || null;
// Any venue display name ("Villanova", "Villanova Wildcats", "St. John's (NY)") -> Kalshi code | null.
function codeForName(name) {
  const t = D1.d1Team(name);
  const x = t ? teamByEspn(t.espnId) : null;
  return x ? x.code : null;
}
const codeForPoly = (abbr) => { const t = teamByPoly(abbr); return t ? t.code : null; };
const codeForEspnId = (id) => { const t = teamByEspn(id); return t ? t.code : null; };

module.exports = {
  splitBlob, teamByCode, teamByPoly, teamByEspn, codeForName, codeForPoly, codeForEspnId,
  generatedAt: data.generatedAt || null,
  teamCount: byCode.size,
  unmatchedKalshi: data.unmatchedKalshi || [],
  unmatchedPoly: data.unmatchedPoly || [],
};
